-- AT-181: the Day 5 substrate migration — PART 1, the eight items Mia (owner)
-- approved on 8 Oct 2026 (recorded on Jira AT-181). Spec: docs/FAVO_PRD_v7.md
-- §10.3 and §10.6. Generated by drizzle-kit from db/schema.ts + db/enums.ts,
-- then hand-edited where noted.
--
--   1. customers.status (customer_status: office_staff | church_member)
--   2. customers.surname (owner decision AT-180; no backfill)
--   3. staff_entitlement_log.staff_id -> customer_id, FK to customers,
--      UNIQUE(customer_id, day). The table name stays (PRD §10.3).
--   4. order_items.shots, CHECK BETWEEN 1 AND 4 (T15 outer ceiling)
--   5. order_items.discount_zar, comp_reason (comp_reason enum), and
--      CHECK (discount_zar <= quantity * unit_price_zar), CHECK (quantity >= 1)
--      — added 10 Oct 2026 (owner approval, Jira AT-181 comment 50720)
--   6. opening_sessions.mode (session_mode: weekday | sunday | event)
--   8. orders.revenue_day (date, SAST, from the server clock — L07, REQ-039)
--  10. payments: one successful payment per order (REQ-011)
--  11. `Extra Shot` deleted from menu_customisations (PRD §10.3 disposition)
--
-- Items 7 and 9 are pending Nikao and are NOT in this migration.
--
-- Hand edits: (a) the entitlement column is RENAMED in place, not dropped and
-- re-added (drizzle-kit would ask interactively); (b) opening_sessions.mode and
-- orders.revenue_day are added nullable, backfilled, then set NOT NULL, so the
-- migration also applies to a table that already has rows. PRD §13.0 says FAVO
-- starts on a clean database, where both UPDATEs touch zero rows; (c) the
-- Extra Shot DELETE. The reverse is drizzle/down/0033_at181_day5_substrate.down.sql.

-- Guard (owner decision 12 Oct 2026): this migration repoints the entitlement
-- to customers on the assumption of a clean database (PRD §13.0). If any
-- existing row's staff_id is not also a customers.id, stop — touch nothing.
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM "staff_entitlement_log" l
    WHERE NOT EXISTS (SELECT 1 FROM "customers" c WHERE c."id" = l."staff_id")
  ) THEN
    RAISE EXCEPTION 'AT-181/0033 is for the new clean database (PRD §13.0); staff_entitlement_log holds legacy staff-id rows — not migrating, nothing deleted';
  END IF;
END $$;--> statement-breakpoint
CREATE TYPE "public"."customer_status" AS ENUM('office_staff', 'church_member');--> statement-breakpoint
CREATE TYPE "public"."session_mode" AS ENUM('weekday', 'sunday', 'event');--> statement-breakpoint
ALTER TABLE "customers" ADD COLUMN "surname" text;--> statement-breakpoint
ALTER TABLE "customers" ADD COLUMN "status" "customer_status" DEFAULT 'church_member' NOT NULL;--> statement-breakpoint
ALTER TABLE "opening_sessions" ADD COLUMN "mode" "session_mode";--> statement-breakpoint
-- Legacy-row backfill only (zero rows on a clean database). A pre-existing
-- Saturday row gets 'event' purely so SET NOT NULL cannot fail: PRD §4.2 says
-- a Saturday social is an event. Saturday has no default mode, and the app
-- refuses every new Saturday session (src/lib/session-mode.ts, SATURDAY_CLOSED).
UPDATE "opening_sessions" SET "mode" = (CASE EXTRACT(ISODOW FROM "session_date"::date) WHEN 7 THEN 'sunday' WHEN 6 THEN 'event' ELSE 'weekday' END)::"session_mode" WHERE "mode" IS NULL;--> statement-breakpoint
ALTER TABLE "opening_sessions" ALTER COLUMN "mode" SET NOT NULL;--> statement-breakpoint
ALTER TABLE "order_items" ADD COLUMN "shots" integer DEFAULT 1 NOT NULL;--> statement-breakpoint
ALTER TABLE "order_items" ADD CONSTRAINT "order_items_shots_range" CHECK (shots BETWEEN 1 AND 4);--> statement-breakpoint
ALTER TABLE "orders" ADD COLUMN "revenue_day" date;--> statement-breakpoint
UPDATE "orders" SET "revenue_day" = ("placed_at" AT TIME ZONE 'Africa/Johannesburg')::date WHERE "revenue_day" IS NULL;--> statement-breakpoint
ALTER TABLE "orders" ALTER COLUMN "revenue_day" SET NOT NULL;--> statement-breakpoint
ALTER TABLE "staff_entitlement_log" DROP CONSTRAINT "staff_entitlement_log_staff_id_day_unique";--> statement-breakpoint
ALTER TABLE "staff_entitlement_log" DROP CONSTRAINT "staff_entitlement_log_staff_id_staff_id_fk";--> statement-breakpoint
ALTER TABLE "staff_entitlement_log" RENAME COLUMN "staff_id" TO "customer_id";--> statement-breakpoint
ALTER TABLE "staff_entitlement_log" ADD CONSTRAINT "staff_entitlement_log_customer_id_customers_id_fk" FOREIGN KEY ("customer_id") REFERENCES "public"."customers"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "staff_entitlement_log" ADD CONSTRAINT "staff_entitlement_log_customer_id_day_unique" UNIQUE("customer_id","day");--> statement-breakpoint
CREATE UNIQUE INDEX "payments_one_successful_per_order" ON "payments" USING btree ("order_id") WHERE status = 'successful';--> statement-breakpoint
DELETE FROM "menu_customisations" WHERE "name" = 'Extra Shot';--> statement-breakpoint
CREATE TYPE "public"."comp_reason" AS ENUM('wrong_drink', 'wrong_charge', 'spillage', 'staff_error', 'goodwill', 'donation');--> statement-breakpoint
ALTER TABLE "order_items" ADD COLUMN "discount_zar" integer DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE "order_items" ADD COLUMN "comp_reason" "comp_reason";--> statement-breakpoint
ALTER TABLE "order_items" ADD CONSTRAINT "order_items_discount_within_line" CHECK (discount_zar <= quantity * unit_price_zar);--> statement-breakpoint
ALTER TABLE "order_items" ADD CONSTRAINT "order_items_quantity_positive" CHECK (quantity >= 1);
